import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第三十七章 多次的播种才能多次的收获果实","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/37第三十七章 多次的播种才能多次的收获果实.md","filePath":"meditation/巴利文大藏经/37第三十七章 多次的播种才能多次的收获果实.md"}'),o={name:"meditation/巴利文大藏经/37第三十七章 多次的播种才能多次的收获果实.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第三十七章-多次的播种才能多次的收获果实" tabindex="-1">第三十七章 多次的播种才能多次的收获果实 <a class="header-anchor" href="#第三十七章-多次的播种才能多次的收获果实" aria-label="Permalink to &quot;第三十七章 多次的播种才能多次的收获果实&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应12经/优达亚经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，佛陀中午穿好法衣，拿着饭钵，进入舍卫城挨家挨户，不分贫富贵贱的化缘饭食，有个叫优陀亚的婆罗门看见佛陀来到自己的住处，就将佛陀的饭钵盛满米饭和斋菜。</p><p>几天后，佛陀第二次来到优陀亚婆罗门的住处，优陀亚婆罗门又恭敬的供养给佛陀可口的饭菜。</p><p>又过了几天，佛陀第三次来到优陀亚婆罗门的住处，优陀亚婆罗门有点厌烦的对佛陀说到：“出家人乔达摩（佛陀），你怎么一而再，再而三，不厌其烦的来我这里索取供养？你难道是贪求我们家的饭菜比别人家的更可口、更好吃吗？”</p><p>佛陀说：“婆罗门，如来挨家挨户，不分贫富贵贱的化缘饭食，多次来你这里化缘也是因缘际会的结果。</p><p>婆罗门，你要明白，种子会被多次的播种下去，天空会多次的降下雨水。农夫多次的播种、施肥、耕耘田地，才能多次的收获果实。出家人、修行人多次的化缘饭食，修习施舍和布施的人多次的供养出家人、修行人。这些布施供养出家人、修行人的施主，他们多次的为自己种植下很多福德和功德，他们由此多次的投生到天界享福。世间的人多次的挤牛奶，他们就能多次的获得牛奶。母牛多次的怀上小牛，就能多次的生出牛犊。世间人无数次的疲倦、劳累、痛苦。世间人无数次的死去，无数次的死后埋葬到地下。世间人的身体无数次的腐烂变成白骨，他们又无数次的投生在世间去承受煎熬和痛苦。</p><p>世间人无数次的生死轮回，无数次的在生死轮回中受尽痛苦和折磨，还不知道要多行善事为自己多种植福德功德，以此种植出来的福德功德生到富贵之家，上生到天界享福，甚至于从生死轮回的煎熬和痛苦中永远的解脱出来。他们还在愚痴的做下无数的恶事，还在给自己造下无数的罪业，这些罪业让他们生到贫贱之家，下堕到地狱、饿鬼、畜生三恶道，让他们受尽痛苦和折磨，他们真是可怜的人，如来虽然知道他们沉沦在生死轮回的痛苦和折磨中，可是他们不相信如来的教导，不按如来的正法去修行，去断恶修善，去多行善事，如来也没有办法帮助到他们。如来虽然有让众生从生死轮回中解脱出来的修行方法，可是众生不依法修行，如来也无法救助他们，就如同生重病的人，不愿意相信医师能够治好他们的病，不愿意服下医师开出的药。不吃药，不按医师所说的方法去治疗病症，医师也无法治好重病的人，也无法帮助他们除去病症，让他们从病痛中解脱出来。”</p><p>这时，佛陀说偈言：</p><p>「屡屡播种子，屡屡降天雨。</p><p>屡屡耕农田，屡屡谷类实。</p><p>屡屡乞食食，屡施施主食。</p><p>屡屡施主施，屡屡行天界。</p><p>屡屡挤牛乳，屡求犊母牛。</p><p>屡屡疲劳苦，愚者屡入胎。</p><p>屡屡于生死，屡屡送墓场。」</p><p>佛陀说法后，优陀亚婆罗门跪在地上对佛陀说：“大德，请您原谅我刚才无礼的言行，我在您这里忏悔，我以后再也不会无端的怀疑和指责出家人和修行人了，请您让我皈依您，做您的在家修行弟子吧，我愿意受持您制定的戒律，我愿意按您的正法去修行。”</p><p>佛陀接受了优陀亚婆罗门的皈依。</p>',19)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
